'use strict';
(() => {
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const url = (s) => { try { const u = new URL(s); return u.protocol === 'https:' ? esc(u.href) : '#sources'; } catch { return '#sources'; } };
  const sources = [...(window.BP_RESEARCH || []),
    {id:'pbms',title:'The pricing investigation extends beyond manufacturers',publisher:'Federal Trade Commission',date:'14 January 2025 · study period 2017–2022',url:'https://www.ftc.gov/news-events/news/press-releases/2025/01/ftc-releases-second-interim-staff-report-prescription-drug-middlemen',fact:'FTC staff analysed 51 specialty generic drugs and reported over $7.3 billion in dispensing revenue above estimated acquisition costs at pharmacies affiliated with the three largest PBMs.',interpretation:'Vertical integration can affect whose pharmacy receives business and where revenue accumulates.',limit:'An interim staff analysis, not an adjudicated finding of illegality. Acquisition-cost benchmarks are not a complete accounting of operating costs or profit.'},
    {id:'antibiotics',title:'Count useful innovation, not only pipeline products',publisher:'World Health Organization',date:'14 June 2024 · pipeline as of December 2023',url:'https://www.who.int/news/item/14-06-2024-who-releases-report-on-state-of-development-of-antibacterials',fact:'WHO identified innovation gaps in the antibacterial pipeline and barriers to access after authorisation.',interpretation:'A pipeline count cannot show whether new products address the greatest unmet need or reach patients.',limit:'A historical snapshot. Innovation criteria and the subgroup targeting priority pathogens differ from the broader pipeline count.'}
  ];
  const stages = [
    {title:'Who paid for the possibility?',body:'Basic research, clinical development and manufacturing are different contributions. Publicly funded science can reveal a target; private firms can bear substantial development and commercial risks. Treating either sector as the sole inventor erases how the system works.',incentive:'Future revenue helps determine which projects receive investment. A promising scientific target without a credible market can struggle to attract capital.',test:'Ask who funded each stage, which risks were borne, and whether the final product offers meaningful additional benefit.',ref:'nih',link:'Public science and new approvals'},
    {title:'Who controls the question?',body:'The trial comparator, selected patients, follow-up and outcome measures can make a study more or less useful. Randomisation addresses one important source of bias; it does not make every research question clinically relevant.',incentive:'A sponsor needs evidence that supports approval and adoption. Patients need evidence that supports a real choice between options.',test:'Find the registration and protocol. Check the primary endpoint, changes to the analysis plan and whether all completed studies are visible.',ref:'registration',link:'Registration and reporting'},
    {title:'How much uncertainty is acceptable?',body:'Faster access can matter in serious disease. Accelerated approval accepts a surrogate reasonably likely to predict clinical benefit, with an obligation to confirm that benefit. Early access moves some uncertainty from development into clinical use.',incentive:'Patients may want access before long-term outcomes are known; the sponsor gains a market while confirmation is still pending.',test:'Look for the approval pathway, outstanding confirmatory study, its recruitment status, and the consequence of a negative or delayed result.',ref:'accelerated',link:'FDA accelerated approval'},
    {title:'Who has a credible alternative?',body:'Bargaining power depends on available substitutes, exclusivity, purchasing rules and the ability to decline a price. A list price does not disclose every discount and a low net price does not guarantee a low patient payment.',incentive:'Manufacturers, payers and intermediaries optimise different revenues and budgets. Their incentives do not necessarily align with the patient at the pharmacy.',test:'Identify the price measure, the comparison period, and the payer. Separate lawful exclusivity from conduct that unlawfully blocks competition.',ref:'patents',link:'Patents versus regulatory exclusivity'},
    {title:'Can the patient actually obtain it?',body:'Registration does not build a supply chain. Medicines need dependable quality, distribution, diagnosis and a way to pay. Access can fail because a product is expensive—or because reliable production is not adequately rewarded.',incentive:'Procurement focused only on the lowest short-term price can neglect resilience. High prices elsewhere can exclude patients even when supply is plentiful.',test:'Measure stock-outs, affordability, quality and access to appropriate treatment—not just approval counts or launch announcements.',ref:'essential',link:'WHO essential medicines framework'}
  ];
  function setStage(i){const s=stages[i];$('stage-detail').innerHTML=`<div><h3>${s.title}</h3><p>${s.body}</p></div><div><strong>The incentive</strong><p>${s.incentive}</p><strong>The accountability test</strong><p>${s.test}</p><a class="source-link" href="#research-${s.ref}">${s.link} ↗</a></div>`;document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===i)));}
  document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>setStage(+b.dataset.stage)));setStage(0);
  const fmt = n => new Intl.NumberFormat('en-AU',{maximumFractionDigits:1}).format(n);
  function risk(){const b=+$('baseline').value/100,r=+$('reduction').value/100,arr=b*r;const untreated=b*1000,treated=untreated*(1-r);$('baseline-value').textContent=fmt(b*100)+'%';$('reduction-value').textContent=fmt(r*100)+'%';$('untreated').textContent=fmt(untreated)+' / 1,000';$('treated').textContent=fmt(treated)+' / 1,000';$('untreated-bar').style.width=(b*100)+'%';$('treated-bar').style.width=(b*(1-r)*100)+'%';$('prevented').textContent=fmt(arr*1000);$('nnt').textContent=arr>0?Math.ceil(1/arr-1e-10).toLocaleString('en-AU'):'∞';$('risk-summary').textContent=`Absolute risk reduction: ${fmt(arr*100)} percentage points. ${arr===0?'In this model, there is no benefit.':'The relative headline stays incomplete without the starting risk and follow-up.'}`;}
  $('baseline').addEventListener('input',risk);$('reduction').addEventListener('input',risk);risk();
  const cases = window.BP_CASES || [];
  function caseHTML(c){const dot=c.outcome.includes('Criminal')?'rust':c.outcome.includes('Deferred')?'gold':'olive';return `<details class="case-file" id="case-${esc(c.id)}"><summary><span class="case-year">${esc(c.year)}</span><span><span class="case-company">${esc(c.company)}</span><span class="case-title">${esc(c.title)}</span><span class="case-outcome"><i class="dot ${dot}"></i>${esc(c.outcome)} · ${esc(c.category)}</span></span><span class="case-amount">${esc(c.amountLabel)}<small>nominal USD · see terms</small></span><span class="case-toggle" aria-hidden="true">+</span></summary><div class="case-details"><p class="case-summary">${esc(c.summary)}</p><div class="case-detail-grid"><div><h4>The record</h4><p>${esc(c.detail)}</p></div><div><h4>Why it matters</h4><p>${esc(c.lesson)}</p></div></div><p class="case-limit"><b>What this does not establish</b>${esc(c.limit)}</p><div class="case-sources">${c.sources.map(s=>`<a href="${url(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} · ${esc(s.date)} ↗</a>`).join('')}<a class="case-permalink" href="#case-${esc(c.id)}">Link to this case</a></div></div></details>`;}
  function renderCases(){const query=$('case-search').value.toLowerCase().trim(),cat=$('case-category').value,sort=$('case-sort').value;const filtered=cases.filter(c=>(cat==='all'||cat===c.category)&&[c.company,c.title,c.summary,c.detail,c.lesson,c.category,c.outcome].join(' ').toLowerCase().includes(query));filtered.sort((a,b)=>sort==='company'?a.company.localeCompare(b.company):sort==='old'?a.year-b.year:b.year-a.year);$('cases').innerHTML=filtered.map(caseHTML).join('');$('case-count').textContent=`${filtered.length} of ${cases.length} case files · selected historical record`;$('empty').hidden=filtered.length>0;}
  $('case-search').addEventListener('input',renderCases);$('case-category').addEventListener('change',renderCases);$('case-sort').addEventListener('change',renderCases);
  function reset(){ $('case-search').value='';$('case-category').value='all';$('case-sort').value='new';renderCases(); }
  $('reset-filters').addEventListener('click',reset);$('empty-reset').addEventListener('click',reset);renderCases();
  const reforms=[
    ['Make the research record complete','Require timely registration, preserve original protocols and make results discoverable even when they disappoint. Fund the work needed to prepare usable results and data.','Percentage of eligible trials reported on time; protocol-to-publication discrepancies; time to resolve missing results.','An uploaded result is not a validated result. Privacy, consent and the risk of re-identification need proper data governance.','registration'],
    ['Make early access accountable','Treat confirmatory research as an obligation with public milestones, rather than an indefinite promise after market entry.','Recruitment before approval; time to completed confirmatory evidence; timely action when benefit is not verified.','Waiting can deny access to seriously ill patients. The right response is explicit uncertainty and enforceable follow-up, not pretending early evidence is final.','confirmatory'],
    ['Protect competition that reaches patients','Scrutinise exclusionary conduct and collusion. Compare net spending and patient costs after entry, not simply the number of approved competitors.','Time from lawful entry to meaningful uptake; net-price changes; pharmacy availability; patient out-of-pocket costs.','Price competition cannot compensate for manufacturing collapse. Purchasing must also support dependable quality and supply.','generics'],
    ['Pay for valuable and reliable treatment','Evaluate additional clinical benefit and reward supply resilience. Make the objective of each payment clear: research, availability, quality or doses delivered.','Patient-important outcomes; stock-outs; quality failures; access across income and geography.','A low purchase price can be expensive if treatment is unavailable. A high price can divert resources from more valuable care.','shortages'],
    ['Make sanctions change decisions','Separate corporate payments from individual responsibility. Inspect monitoring, sales incentives, compliance obligations and the consequences of repeat conduct.','Repeated substantiated violations; implementation of ordered controls; recovery actually collected; independence of oversight.','A bigger announced liability is not automatically a stronger deterrent. Bankruptcy, insurance, credits and enforcement delays can change its effect.',''],
    ['Make conflicts visible and manageable','Disclose relevant financial relationships and assess whether they influence education, procurement, research and prescribing.','Completeness of disclosures; independent review of high-risk relationships; changes in institutional policies and behaviour.','Disclosure alone can become a ritual. It needs credible rules about when a relationship should be limited or excluded.','cochrane']
  ];
  $('reforms').innerHTML=reforms.map((r,i)=>`<article class="reform"><span class="reform-num">0${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p>${r[4]?`<a class="source-link" href="#research-${r[4]}">Related evidence ↗</a>`:'<a class="source-link" href="#casebook">See enforcement case files ↗</a>'}</div><div><h4>Measure this</h4><p>${r[2]}</p><h4>The trade-off</h4><p class="tradeoff">${r[3]}</p></div></article>`).join('');
  $('research-notes').innerHTML=sources.map((s,i)=>`<details class="research-note" id="research-${esc(s.id)}"><summary><span>${String(i+1).padStart(2,'0')} / ${esc(s.title)}</span><small>${esc(s.publisher)} · ${esc(s.date)}</small></summary><div class="research-content"><p><b>The finding.</b> ${esc(s.fact)}</p><p><b>Why it belongs here.</b> ${esc(s.interpretation)}</p><p class="limit"><b>The limit.</b> ${esc(s.limit)}</p><a href="${url(s.url)}" target="_blank" rel="noopener noreferrer">Read the primary source ↗</a></div></details>`).join('');
  function revealHash(){const id=decodeURIComponent(location.hash.slice(1));if(!id)return;const el=$(id);if(el?.tagName==='DETAILS'){el.open=true;requestAnimationFrame(()=>el.scrollIntoView({block:'start'}));}}
  window.addEventListener('hashchange',revealHash);revealHash();
  document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#research-"]');if(a){const el=$(a.getAttribute('href').slice(1));if(el)el.open=true;}});
  function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);}
  $('download-cases').addEventListener('click',()=>download('BigPharma2-casebook.json',{edition:'2026-11-04',scope:'Curated historical sample. Not a safety ranking. Nominal USD; amounts must not be summed.',cases}));
  $('download-research').addEventListener('click',()=>download('BigPharma2-research.json',{edition:'2026-11-04',sources}));
  let openBeforePrint=[];window.addEventListener('beforeprint',()=>{openBeforePrint=[...document.querySelectorAll('details')].filter(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true);});window.addEventListener('afterprint',()=>{document.querySelectorAll('details').forEach(d=>d.open=openBeforePrint.includes(d));});$('print').addEventListener('click',()=>window.print());
  function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';}addEventListener('scroll',progress,{passive:true});progress();
})();
